let usdtToman = null;
let fxSource = 'fallback';
try {
  const wallex = $('FX1. Wallex Live USDT/TMN').first()?.json;
  const parsed = parseFloat(wallex?.result?.symbols?.USDTTMN?.stats?.lastPrice);
  if (Number.isFinite(parsed) && parsed > 10000) {
    usdtToman = Math.round(parsed);
    fxSource = 'wallex_live';
  }
} catch (e) {}

let usdFreeToman = null;
try {
  const tgju = $('FX2. TGJU Free FX (USD/EUR/AED)').first()?.json;
  const rows = tgju?.rows || [];
  const usdRow = rows.find(r => /dollar/i.test(String(r.symbol || '')) || String(r.name || '').includes('دلار'));
  const usdtRow = rows.find(r => /usdt/i.test(String(r.symbol || '')) || String(r.name || '').includes('تتر'));
  if (usdRow?.price_toman) usdFreeToman = Math.round(Number(usdRow.price_toman));
  if (!usdtToman && usdtRow?.price_toman) {
    usdtToman = Math.round(Number(usdtRow.price_toman));
    fxSource = 'tgju_proxy';
  }
} catch (e) {}

const cnyToUsd = $('FX3. CNY/USD Parity Converter').first()?.json?.cny_to_usd || 0.14;
const gasUsd = $('FX4. Network Gas Estimator (BSC/TRC20)').first()?.json?.gas_usd || { 'BSC/BEP20': 0.15 };

return [{ json: {
  usdt_toman: usdtToman,
  usd_free_toman: usdFreeToman,
  cny_to_usd: cnyToUsd,
  gas_usd: gasUsd,
  fx_source: fxSource,
  fx_error: usdtToman === null,
  fetched_at: new Date().toISOString()
} }];

const DEFAULT_USDT = 272100;
const store = $getWorkflowStaticData('global');
const incoming = $json;

let resolvedUsdt = incoming.usdt_toman;
let source = incoming.fx_source;
if (resolvedUsdt && resolvedUsdt > 10000) {
  store.last_good_fx = { usdt_toman: resolvedUsdt, saved_at: incoming.fetched_at };
} else if (store.last_good_fx?.usdt_toman) {
  resolvedUsdt = store.last_good_fx.usdt_toman;
  source = 'cached_static_data';
} else {
  resolvedUsdt = DEFAULT_USDT;
  source = 'hardcoded_2026_fallback';
}

const cnyToUsd = incoming.cny_to_usd || 0.14;
return [{ json: {
  usdt_toman: resolvedUsdt,
  usd_free_toman: incoming.usd_free_toman || Math.round(resolvedUsdt * 1.004),
  eur_toman: Math.round(resolvedUsdt * 1.08),
  aed_toman: Math.round(resolvedUsdt / 3.6725),
  cny_to_usd: cnyToUsd,
  cny_toman: Math.round(resolvedUsdt * cnyToUsd),
  gas_usd: incoming.gas_usd,
  fx_source: source,
  fx_outage: Boolean(incoming.fx_error),
  fetched_at: incoming.fetched_at
} }];

