  { json: { sku_id: 'teamorouter-100', product_type: 'api_credit', name_fa: 'اعتبار گیت‌وی API تیموروتر (۱۰۰ دلار)', source_name: 'TeamoRouter', source_url: 'https://teamorouter.com/blogs/ai-api-crypto-payment', raw_cost: 82.00, network_gas_usd: 0.15, gateway_fee_pct: 0, market_benchmark_toman: 29500000, currency_basis: 'USDT', payment_asset: 'USDT', payment_network: 'BSC/BEP20', delivery_method: 'API Balance', ban_coverage: 'unknown', promotion_status: 'not_found', is_c2c: false } }
];

const ads = $json.ads || $json.results || [];
const cleaned = ads.filter(a => Number(a.price) > 0).map(a => ({ ...a, is_urgent: String(a.title || '').includes('فوری') || a.tag === 'فوری' }));
return [{ json: { collector: 'divar_urgent', ads: cleaned, count: cleaned.length } }];

const fx = $('FX6. FX Cache & Outage Fallback').first()?.json || { usdt_toman: 272100, cny_to_usd: 0.14 };
const collect = (name) => { try { return $(name).all().map(i => i.json); } catch (e) { return []; } };

const physicalSeed = [
  ...collect('W1. Apple Ecosystem Watchlist'),
  ...collect('W2. Gaming Consoles Watchlist'),
  ...collect('W3. PC Hardware & NVMe SSD'),
  ...collect('W4. Used C2C Mobile (iPhone 13/14)')
];
const digitalSeed = [
  ...collect('W5. Consumer AI Subscriptions'),
  ...collect('W6. AI Coding IDEs (Cursor Pro)'),
  ...collect('W7. Creative & Media Tools'),
  ...collect('W8. API Credit Gateways')
];

const torobPicks = collect('C1. Torob Median Baseline').flatMap(x => x.picks || []);
const techProds = collect('C5. Technolife Flash Deals').flatMap(x => x.products || []);
const dkProds = collect('C3. Digikala Flash Campaigns').flatMap(x => x.products || []);

const signals = [];
let seq = 1;

for (const p of physicalSeed) {
  const matchedTorob = torobPicks.find(t => String(t.title || '').includes(p.query.split(' ')[0]));
  const marketMedian = Number(matchedTorob?.stats?.median) || p.fallback_market;
  const matchedTech = techProds.find(t => String(t.title || '').includes(p.query.split(' ')[0]));
  const matchedDk = dkProds.find(t => String(t.title || '').includes(p.query.split(' ')[0]));
  const liveSale = p.is_c2c ? p.fallback_cost : (Number(matchedTech?.final_price || matchedDk?.price) || p.fallback_cost);
  const liveBefore = p.is_c2c ? null : (Number(matchedTech?.price_before_discount || matchedDk?.price_before_discount) || p.fallback_before);
  const sourceName = p.is_c2c ? 'دیوار تهران (C2C)' : (matchedTech ? 'تکنولایف' : matchedDk ? 'دیجیکالا' : 'حراجی بلک‌فرایدی داخلی');
  const sourceUrl = p.is_c2c ? 'https://divar.ir' : (matchedTech?.url || matchedDk?.url || 'https://www.technolife.ir');

  signals.push({ json: {
    tracking_id: `deal-2026-bf-${String(seq++).padStart(3, '0')}`,
    sku_id: p.sku_id,
    product_type: p.product_type,
    name_fa: p.name_fa,
    source_name: sourceName,
    source_url: sourceUrl,
    payment_asset: p.payment_asset,
    payment_network: p.payment_network,
    currency_basis: p.currency_basis,
    raw_cost: liveSale,
    price_before_discount: liveBefore,
    network_gas_usd: 0,
    gateway_fee_pct: 0,
    exchange_rate_toman: fx.usdt_toman,
    cny_to_usd: fx.cny_to_usd,
    market_benchmark_toman: marketMedian,
    torob_min: Number(matchedTorob?.stats?.min) || Math.round(marketMedian * 0.88),
    torob_max: Number(matchedTorob?.stats?.max) || Math.round(marketMedian * 1.12),
    delivery_method: p.delivery_method,
    ban_coverage: p.ban_coverage,
    promotion_status: liveBefore && liveBefore > liveSale ? 'verified_bf' : 'standard_price',
    is_c2c: Boolean(p.is_c2c)
  } });
}

for (const d of digitalSeed) {
  signals.push({ json: {
    tracking_id: `deal-2026-bf-${String(seq++).padStart(3, '0')}`,
    sku_id: d.sku_id,
    product_type: d.product_type,
    name_fa: d.name_fa,
    source_name: d.source_name,
    source_url: d.source_url,
    payment_asset: d.payment_asset,
    payment_network: d.payment_network,
    currency_basis: d.currency_basis,
    raw_cost: d.raw_cost,
    price_before_discount: null,
    network_gas_usd: d.network_gas_usd || 0.15,
    gateway_fee_pct: d.gateway_fee_pct || 0,
    exchange_rate_toman: fx.usdt_toman,
    cny_to_usd: fx.cny_to_usd,
    market_benchmark_toman: d.market_benchmark_toman,
    torob_min: Math.round(d.market_benchmark_toman * 0.92),
    torob_max: Math.round(d.market_benchmark_toman * 1.08),
    delivery_method: d.delivery_method,
    ban_coverage: d.ban_coverage,
    promotion_status: d.promotion_status || 'not_found',
    is_c2c: false
  } });
}

return signals;

return items.map(item => {
  const d = item.json;
  const hasBefore = d.price_before_discount !== null && d.price_before_discount !== undefined && Number(d.price_before_discount) > 0;
  const discountVerified = hasBefore ? Number(d.price_before_discount) > Number(d.raw_cost) : true;
  return { json: {
    ...d,
    discount_verified: discountVerified,
    promotion_status: discountVerified ? d.promotion_status : 'fake_promo'
  } };
});

const DIVAR_SCAM_FLOOR = 0.40;
return items.map(item => {
  const d = item.json;
  const ratio = d.market_benchmark_toman > 0 ? d.raw_cost / d.market_benchmark_toman : 1;
  const manualReview = Boolean(d.is_c2c && ratio < DIVAR_SCAM_FLOOR);
  return { json: {
    ...d,
    c2c_market_ratio: Number(ratio.toFixed(2)),
    manual_review_required: manualReview
  } };
});

const LIQUIDITY_CAP_TMN = 45000000;
return items.map(item => {
  const d = item.json;
  const estimatedCost = d.currency_basis === 'TOMAN' ? d.raw_cost : Math.round(d.raw_cost * d.exchange_rate_toman);
  const withinCap = d.product_type === 'physical_tech' ? estimatedCost <= LIQUIDITY_CAP_TMN : true;
  return { json: { ...d, within_liquidity_cap: withinCap, liquidity_cap_toman: LIQUIDITY_CAP_TMN } };
});

const VALID_RAILS = new Set(['Shaparak', 'Domestic Bank', 'BSC/BEP20', 'TRON/TRC20', 'Base/Polygon', 'Alipay/CNY']);
return items.map(item => {
  const d = item.json;
  const railOk = VALID_RAILS.has(d.payment_network);
  return { json: { ...d, payment_rail_verified: railOk } };
});

const now = new Date().toISOString();
return items.map(item => ({
  json: {
    ...item.json,
    evidence_type: item.json.product_type === 'physical_tech' ? 'http_mcp_collector' : 'crypto_storefront_snapshot',
    verified_at: now
  }
}));

const LABELS_FA = {
  supported: 'تحت پوشش گارانتی / معتبر',
  excluded: 'بدون گارانتی بن (Excluded)',
  unknown: 'نامشخص (نیاز به تایید دستی)'
};
return items.map(item => {
  const cov = ['supported', 'excluded', 'unknown'].includes(item.json.ban_coverage) ? item.json.ban_coverage : 'unknown';
  return { json: { ...item.json, ban_coverage: cov, ban_coverage_fa: LABELS_FA[cov] } };
});

return items.map(item => {
  const d = item.json;
  const spread = d.market_benchmark_toman > 0 ? ((d.torob_max - d.torob_min) / d.market_benchmark_toman) * 100 : 0;
  return { json: { ...d, volatility_pct: Number(spread.toFixed(1)) } };
});

return items.map(item => {
  const d = item.json;
  const feeMul = 1 + (Number(d.gateway_fee_pct || 0) / 100);
  let totalToman = 0;
  if (d.currency_basis === 'TOMAN') {
    totalToman = Math.round(Number(d.raw_cost) * feeMul);
  } else if (d.currency_basis === 'USDT' || d.currency_basis === 'USDC') {
    totalToman = Math.round((Number(d.raw_cost) * feeMul + Number(d.network_gas_usd || 0)) * Number(d.exchange_rate_toman));
  } else if (d.currency_basis === 'CNY') {
    totalToman = Math.round((Number(d.raw_cost) * Number(d.cny_to_usd || 0.14) * feeMul + Number(d.network_gas_usd || 0)) * Number(d.exchange_rate_toman));
  }
  return { json: { ...d, total_cost_toman: Math.max(1, totalToman) } };
});

return items.map(item => ({
  json: {
    ...item.json,
    net_profit_toman: Math.round(Number(item.json.market_benchmark_toman) - Number(item.json.total_cost_toman))
  }
}));

return items.map(item => {
  const cost = Math.max(1, Number(item.json.total_cost_toman));
  const margin = Number(((Number(item.json.net_profit_toman) / cost) * 100).toFixed(1));
  return { json: { ...item.json, margin_pct: margin } };
});

return items.map(item => ({
  json: {
    ...item.json,
    roi_pct: item.json.margin_pct,
    cost_usd_equivalent: Number((item.json.total_cost_toman / Math.max(1, item.json.exchange_rate_toman)).toFixed(2))
  }
}));

const BUDGET_TMN = 100000000;
return items.map(item => ({
  json: {
    ...item.json,
    budget_capacity_units: Math.floor(BUDGET_TMN / Math.max(1, Number(item.json.total_cost_toman)))
  }
}));

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fa = n => Math.round(Number(n || 0)).toLocaleString('fa-IR');

return items.map(item => {
  const d = item.json;
  let dealGrade = 'DROP';
  if (d.manual_review_required) {
    dealGrade = 'MANUAL_REVIEW';
  } else if (d.discount_verified && d.within_liquidity_cap && d.margin_pct >= 30) {
    dealGrade = 'A+';
  } else if (d.discount_verified && d.within_liquidity_cap && d.margin_pct >= 18) {
    dealGrade = 'A';
  }

  const header = dealGrade === 'A+'
    ? '🔥 <b>فرصت طلایی Grade A+ بلک فرایدی ۲۰۲۶</b>'
    : dealGrade === 'MANUAL_REVIEW'
      ? '⚠️ <b>صف بررسی دستی ادمین (آگهی زیر ۴۰٪ دیوار)</b>'
      : '🎯 <b>فرصت استاندارد Grade A بلک فرایدی ۲۰۲۶</b>';

  const html = [
    header,
    '',
    `📦 <b>محصول:</b> ${esc(d.name_fa)}`,
    `🏷 <b>نوع قرارداد:</b> ${esc(d.product_type)} | <b>رتبه:</b> ${dealGrade}`,
    `🏪 <b>منبع تأمین:</b> ${esc(d.source_name)} (${esc(d.payment_asset)} / ${esc(d.payment_network)})`,
    `💰 <b>قیمت خرید تمام‌شده:</b> ${fa(d.total_cost_toman)} تومان`,
    `📊 <b>قیمت بازار (میانه ترب):</b> ${fa(d.market_benchmark_toman)} تومان`,
    `✅ <b>سود خالص معامله:</b> ${fa(d.net_profit_toman)} تومان`,
    `📈 <b>حاشیه سود / ROI:</b> ${d.margin_pct}%`,
    `🛡 <b>وضعیت گارانتی بن:</b> ${esc(d.ban_coverage_fa)} · تحویل: ${esc(d.delivery_method)}`,
    `🧮 <b>ظرفیت خرید با بودجه ۱۰۰ م:</b> ${d.budget_capacity_units} عدد`,
    '',
    `🔗 <a href="${esc(d.source_url)}">مشاهده و خرید مستقیم</a>`
  ].join('\n');

  return { json: { ...d, deal_grade: dealGrade, telegram_html: html } };
});

const DEDUPE_HOURS = 6;
const store = $getWorkflowStaticData('global');
store.alerted = store.alerted || {};

if ($input.first()?.json?.reset_dedupe === true) {
  store.alerted = {};
  return [{ json: { status: 'dedupe_memory_cleared', deal_grade: 'DROP', timestamp: new Date().toISOString() } }];
}

const now = Date.now();
for (const k of Object.keys(store.alerted)) {
  if (now - store.alerted[k] > DEDUPE_HOURS * 3600 * 1000) delete store.alerted[k];
}

const out = [];
for (const item of items) {
  const d = item.json;
  if (d.deal_grade === 'DROP') {
    out.push({ json: { ...d, is_new_alert: false } });
    continue;
  }
  const key = `${d.sku_id || d.tracking_id}|${d.total_cost_toman}|${d.deal_grade}`;
  const isNew = !store.alerted[key];
  if (isNew) {
    store.alerted[key] = now;
    out.push({ json: { ...d, is_new_alert: true, dedupe_key: key } });
  }
}
return out;
